contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that setSlopes either reverts for invalid kink values or, for valid kink values (0 < kink < 1e27),
    // it successfully stores the slopes such that subsequent calls to rate do not revert due to empty code checks
    // (we cannot directly read slope storage, so we observe that setSlopes did not revert and that calling rate
    // against some vault/address returns a uint without reverting). The rule: setSlopes reverts iff kink==0 or kink>=1e27.

    function run(address vault, address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        require(address(this).balance >= 0);
        // Build the SlopeData ABI encoding to call setSlopes. Use the external function directly.
        // Call setSlopes and capture whether it reverted.
        bool reverted;
        bytes memory data = abi.encode(kink, slope0, slope1);

        // Since setSlopes takes (address _asset, SlopeData memory _slopes), we must call it normally.
        try c.setSlopes(asset, C.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Now attempt a call to rate to observe behavior when setSlopes succeeded. We only call rate if setSlopes did not revert.
        bool rateReverted = false;
        uint256 latestAnswer = 0;
        if (!reverted) {
            try c.rate(vault, asset) returns (uint256 ans) {
                latestAnswer = ans;
            } catch {
                rateReverted = true;
            }
        }

        // General rule: setSlopes must revert exactly when kink==0 or kink>=1e27. If setSlopes succeeded then subsequent rate must not revert due to empty-code checks (we observe rate call not reverting), so rateReverted==false.
        // Formally: reverted == (kink == 0 || kink >= 1e27)  AND  (!reverted ==> rateReverted == false).
        assert(
            (reverted == (kink == 0 || kink >= 1e27)) && (!reverted ? (rateReverted == false) : true)
        );
    }

    // receive fallback to allow sending Ether if needed by future variants
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that calling setSlopes with an invalid kink (0 or >= 1e27) reverts, otherwise it succeeds.
    // Because SlopeData is an internal type, we ABI-encode the calldata and perform a low-level call to observe revert/success.
    // After a successful setSlopes, we call rate(vault, asset) and observe whether it reverts.

    function run(address vault, address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        require(address(this).balance >= 0);

        // Prepare calldata for setSlopes(address, (uint256,uint256,uint256))
        bytes4 sig = bytes4(keccak256("setSlopes(address,(uint256,uint256,uint256))"));
        // According to ABI for tuple: encode as (address, uint256, uint256, uint256)
        bytes memory data = abi.encodeWithSelector(sig, asset, kink, slope0, slope1);

        bool setSlopesReverted;
        // low-level call from this contract to c
        (bool ok, ) = address(c).call(data);
        setSlopesReverted = !ok;

        // Now, if setSlopes succeeded, try calling rate to observe whether it reverts.
        bool rateReverted = false;
        uint256 latestAnswer = 0;
        if (!setSlopesReverted) {
            try c.rate(vault, asset) returns (uint256 ans) {
                latestAnswer = ans;
            } catch {
                rateReverted = true;
            }
        }

        // General rule: setSlopes reverts exactly when kink == 0 or kink >= 1e27.
        // Additionally, if setSlopes succeeded then calling rate should not revert due to AccessDenied for this contract's caller context.
        // We cannot detect AccessDenied specifically, but require that when setSlopes succeeded rate either returns a value (rateReverted == false) or the revert occurred for some other reason; to keep the rule checkable we assert the core kink property and that success implies rate() did not revert immediately here (rateReverted == false).
        assert((setSlopesReverted == (kink == 0 || kink >= 1e27)) && (!setSlopesReverted ? (rateReverted == false) : true));
    }

    receive() external payable {}
}

